    "text": "次の【決算整理前残高試算表】および【決算整理事項】に基づき、当期の損益計算書（P/L）に計上される【売上原価】および【営業利益】の組み合わせとして正しいものを選択しなさい。\n<div class=\"boki-material-box\">\n  <div class=\"boki-material-title\"><i class=\"fas fa-table\"></i> 資料1：決算整理前残高試算表（令和X1年3月31日）</div>\n  <div class=\"boki-table-wrapper\"><table class=\"boki-table\"><thead><tr><th>借方残高</th><th>勘定科目</th><th>貸方残高</th></tr></thead><tbody><tr><td class=\"num\">￥1,200,000</td><td class=\"\">当座預金</td><td class=\"\"></td></tr><tr><td class=\"num\">￥4,800,000</td><td class=\"\">売掛金</td><td class=\"\"></td></tr><tr><td class=\"\"></td><td class=\"\">貸倒引当金</td><td class=\"num\">￥40,000</td></tr><tr><td class=\"num\">￥1,500,000</td><td class=\"\">繰越商品</td><td class=\"\"></td></tr><tr><td class=\"num\">￥2,000,000</td><td class=\"\">その他有価証券</td><td class=\"\"></td></tr><tr><td class=\"num\">￥10,000,000</td><td class=\"\">建　物</td><td class=\"\"></td></tr><tr><td class=\"\"></td><td class=\"\">建物減価償却累計額</td><td class=\"num\">￥3,600,000</td></tr><tr><td class=\"\"></td><td class=\"\">買掛金</td><td class=\"num\">￥3,200,000</td></tr><tr><td class=\"\"></td><td class=\"\">資本金</td><td class=\"num\">￥8,000,000</td></tr><tr><td class=\"\"></td><td class=\"\">繰越利益剰余金</td><td class=\"num\">￥1,160,000</td></tr><tr><td class=\"\"></td><td class=\"\">売　上</td><td class=\"num\">￥24,000,000</td></tr><tr><td class=\"num\">￥16,500,000</td><td class=\"\">仕　入</td><td class=\"\"></td></tr><tr><td class=\"num\">￥2,800,000</td><td class=\"\">給　料</td><td class=\"\"></td></tr><tr><td class=\"num\">￥800,000</td><td class=\"\">支払家賃</td><td class=\"\"></td></tr><tr><td class=\"num\">￥400,000</td><td class=\"\">水道光熱費</td><td class=\"\"></td></tr><tr><td class=\"num\">￥39,000,000</td><td class=\"\">合　計</td><td class=\"num\">￥39,000,000</td></tr></tbody></table></div>\n</div>\n<div class=\"boki-material-box\">\n  <div class=\"boki-material-title\"><i class=\"fas fa-pen-to-square\"></i> 資料2：決算整理事項</div>\n  \n<ol class=\"boki-sub-items\">\n  <li>期末商品棚卸高は <strong>￥1,800,000</strong> である（仕入勘定で計算）。実地棚卸による減耗損等は生じていない。</li>\n  <li>売掛金の期末残高に対して <strong>2％</strong> の貸倒引当金を差額補充法により設定する。</li>\n  <li>その他有価証券（すべて株式）の期末時価は <strong>￥2,300,000</strong> である。全部純資産直入法（税効果会計適用：実効税率30％）により評価替えを行う。</li>\n  <li>建物について定額法（耐用年数30年、残存価額ゼロ、間接法）により減価償却を行う。</li>\n  <li>支払家賃のうち <strong>￥100,000</strong> は前払いである。</li>\n  <li>給料の未払分が <strong>￥200,000</strong> ある。</li>\n  <li>当期の法人税等として <strong>￥750,000</strong> を計上する。</li>\n</ol>\n</div>",
